\newcommand{\Z}{\mathbb{Z}}

\title{Divisibility of $a^5-a$: An Elementary Proof, Its Sharpenings, and Its Place in Fermat's Little Theorem}
\author{Aristotle}
\date{2026-07-02}

\begin{document}

\begin{abstract}
We give a fully elementary, self-contained treatment of the classical fact that $a^5 - a$ is divisible by $5$ for every integer $a$, together with several genuine strengthenings and a placement of the result inside the general theory. Our primary proof avoids any appeal to finite-field theory or exhaustive residue checking: it rests on a single polynomial identity, $(n+1)^5 - (n+1) = (n^5 - n) + 5(n^4 + 2n^3 + 2n^2 + n)$, propagated across the integers by induction. We then record a complementary factorization $a^5 - a = (a-1)a(a+1)(a^2+1)$, which exposes divisibility by $2$ and $3$; combining these with divisibility by $5$ through coprimality yields the sharper statement $30 \mid a^5 - a$. A further consequence, $a^5 \equiv a \pmod{10}$, establishes that the last decimal digit of any integer is fixed by the fifth-power map. Finally we prove the general Fermat's Little Theorem, $p \mid a^p - a$ for every prime $p$, and recover the $p = 5$ case as a corollary. We discuss algorithms for computing the universal denominator $D(n)$ of $a^n - a$ and outline directions for further research.
\end{abstract}

\maketitle

\section{Introduction}

Among the first surprises in number theory is that certain polynomial expressions in an integer variable are \emph{always} divisible by a fixed number, regardless of the input. The prototype is
\[
5 \mid a^5 - a \qquad \text{for all } a \in \Z.
\]
This paper studies this statement with three goals: to give a proof that is genuinely elementary (using only integer induction and a polynomial identity), to sharpen the modulus from $5$ to its true maximal value $30$, and to situate the result within Fermat's Little Theorem. Along the way we obtain a corollary about decimal last digits and describe the computational structure underlying the family $\{\,p \mid a^p - a\,\}$.

Throughout, for integers $m, x$ we write $m \mid x$ to mean $m$ divides $x$, and $x \equiv y \pmod m$ to mean $m \mid (x-y)$.

\section{Definitions and preliminaries}

\begin{definition}[Defect function]
For an integer $a$, define the \emph{fifth-power defect} by $\Delta(a) := a^5 - a$. More generally, for $n \ge 1$, write $\Delta_n(a) := a^n - a$.
\end{definition}

\begin{definition}[Universal denominator]
For $n \ge 1$, define $D(n) := \gcd\{\, a^n - a : a \in \Z \,\}$, the largest positive integer dividing $a^n - a$ for every integer $a$.
\end{definition}

\begin{lemma}[Coprime gluing]\label{lem:glue}
If $m_1, m_2$ are coprime integers and both $m_1 \mid x$ and $m_2 \mid x$, then $m_1 m_2 \mid x$.
\end{lemma}

\begin{proof}
Coprimality yields integers $u, v$ with $u m_1 + v m_2 = 1$ (B\'ezout). Then $x = x(u m_1 + v m_2) = u m_1 x + v m_2 x$; substituting $x = m_2 y_2 = m_1 y_1$ shows $m_1 m_2$ divides each term, hence $x$. This is the ring-theoretic content of the Chinese Remainder Theorem for a single congruence class.
\end{proof}

\section{The primary result: an inductive proof}

\begin{lemma}[Step identity]\label{lem:step}
For every integer $n$,
\[
(n+1)^5 - (n+1) = (n^5 - n) + 5\,(n^4 + 2n^3 + 2n^2 + n).
\]
\end{lemma}

\begin{proof}
Expand $(n+1)^5 = n^5 + 5n^4 + 10n^3 + 10n^2 + 5n + 1$. Then
\[
(n+1)^5 - (n+1) = (n^5 - n) + (5n^4 + 10n^3 + 10n^2 + 5n),
\]
and the tail equals $5(n^4 + 2n^3 + 2n^2 + n)$.
\end{proof}

\begin{theorem}[Divisibility by five]\label{thm:five}
For every integer $a$, $\;5 \mid a^5 - a$.
\end{theorem}

\begin{proof}
We use integer induction. \emph{Base:} $0^5 - 0 = 0$. \emph{Forward step:} if $n^5 - n = 5k$, then by Lemma~\ref{lem:step}, $(n+1)^5 - (n+1) = 5(k + n^4 + 2n^3 + 2n^2 + n)$. \emph{Backward step:} Lemma~\ref{lem:step} with $n$ replaced by $n-1$ gives $(n-1)^5 - (n-1) = (n^5 - n) - 5\,g(n-1)$ where $g(m) = m^4 + 2m^3 + 2m^2 + m$, so divisibility descends to $n-1$. Induction in both directions covers all of $\Z$.
\end{proof}

The proof never enumerates residue classes; its load-bearing content is Lemma~\ref{lem:step}, expressing that the defect is periodic up to multiples of five.

\section{A structural factorization}

\begin{theorem}[Factorization]\label{thm:fact}
For every integer $a$, $\;a^5 - a = (a-1)\,a\,(a+1)\,(a^2 + 1)$.
\end{theorem}

\begin{proof}
$a^5 - a = a(a^4 - 1) = a(a^2-1)(a^2+1) = a(a-1)(a+1)(a^2+1)$.
\end{proof}

\begin{corollary}\label{cor:two-three}
For every integer $a$, both $2 \mid a^5 - a$ and $3 \mid a^5 - a$.
\end{corollary}

\begin{proof}
The factors $a-1, a, a+1$ are three consecutive integers; one of any two consecutive integers is even and one of any three is a multiple of $3$.
\end{proof}

\section{Sharpening the modulus to thirty}

\begin{theorem}[Divisibility by thirty]\label{thm:thirty}
For every integer $a$, $\;30 \mid a^5 - a$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:five} and Corollary~\ref{cor:two-three}, $2, 3, 5$ each divide $\Delta(a)$. As $2, 3$ are coprime, Lemma~\ref{lem:glue} gives $6 \mid \Delta(a)$; as $6, 5$ are coprime, $30 \mid \Delta(a)$.
\end{proof}

\begin{theorem}[Maximality]\label{thm:max}
$D(5) = 30$: thirty is the largest integer dividing $a^5 - a$ for all $a$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:thirty} gives $30 \mid D(5)$. Evaluating at $a = 2$ gives $\Delta(2) = 30$, so any universal divisor divides $30$; hence $D(5) \mid 30$ and $D(5) = 30$.
\end{proof}

The defects for $a = 0, \ldots, 8$ are $0, 0, 30, 240, 1020, 3120, 7770, 16800, 32760$, whose nonzero entries have gcd exactly $30$.

\section{A consequence for last digits}

\begin{theorem}[Last-digit stability]\label{thm:digit}
For every integer $a$, $\;a^5 \equiv a \pmod{10}$; i.e.\ $a^5$ ends in the same decimal digit as $a$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:five} and Corollary~\ref{cor:two-three}, $5 \mid \Delta(a)$ and $2 \mid \Delta(a)$. As $2, 5$ are coprime, Lemma~\ref{lem:glue} gives $10 \mid a^5 - a$.
\end{proof}

\begin{corollary}[Digit fixed points]
For every $a$ and every $k \ge 0$, $\;a^{5^k} \equiv a \pmod{10}$.
\end{corollary}

\begin{proof}
Induction on $k$; the step uses Theorem~\ref{thm:digit} applied to $a^{5^k}$: $a^{5^{k+1}} = (a^{5^k})^5 \equiv a^{5^k} \equiv a \pmod{10}$.
\end{proof}

\section{Placement within Fermat's Little Theorem}

\begin{theorem}[Fermat's Little Theorem, additive form]\label{thm:flt}
For every prime $p$ and every integer $a$, $\;p \mid a^p - a$.
\end{theorem}

\begin{proof}
In the field of residues modulo $p$, the $p-1$ nonzero elements form a cyclic group of order $p-1$, so $x^{p-1} = 1$ and thus $x^p = x$ for all nonzero $x$; the identity $x^p = x$ is trivial at $x = 0$. Hence $a^p - a \equiv 0 \pmod p$.
\end{proof}

\begin{corollary}
Taking $p = 5$ recovers Theorem~\ref{thm:five}.
\end{corollary}

The elementary inductive proof of Theorem~\ref{thm:five} and the field-theoretic proof of Theorem~\ref{thm:flt} are two faces of the periodicity of $x \mapsto x^p - x$ modulo $p$: the former supplies an explicit witness polynomial, the latter the structural reason and immediate generality.

\section{The universal denominator $D(n)$}

\begin{proposition}[Structure of $D(n)$]\label{prop:Dn}
For each $n \ge 1$, $D(n)$ is squarefree, and a prime $p$ divides $D(n)$ iff $p - 1$ divides $n - 1$. Thus $D(n) = \prod_{\,p:\,(p-1)\mid(n-1)} p$.
\end{proposition}

\begin{proof}
A prime $p$ divides $a^n - a$ for all $a$ iff $x^n = x$ for all $x$ modulo $p$, i.e.\ $x^{n-1} = 1$ for all nonzero $x$, which holds iff the group exponent $p-1$ divides $n-1$. Squarefreeness follows since, for $a = p$, $p^n - p$ is divisible by $p$ but not $p^2$ when $n \ge 2$.
\end{proof}

Thus $D(3) = 6$, $D(5) = 30$, and $D(7) = 42$; note $5 \nmid D(7)$ since $4 \nmid 6$.

\section{Algorithms}

\textbf{Algorithm A (universal denominator).} For each prime $p$ up to a bound, test whether $(p-1) \mid (n-1)$ (equivalently $x^n \equiv x \pmod p$ for all residues $x$); multiply the passing primes. Correctness is Proposition~\ref{prop:Dn}.

\smallskip
\noindent\textbf{Algorithm B (coprime gluing).} Given pairwise coprime $m_1, \ldots, m_r$ each dividing $f(a)$ for all $a$, fold Lemma~\ref{lem:glue} across the factors to certify $m_1 \cdots m_r \mid f(a)$. This is the mechanism passing from $\{2,3,5\}$ to $30$.

\section{Discussion and future directions}

The additive form of Fermat's Little Theorem underpins primality testing and public-key cryptography. The universal-denominator viewpoint reframes scattered ``always divisible'' curiosities as a single classification governed by $(p-1)\mid(n-1)$. Future work includes a full classification of $D(n)$, the study of eventual periodicity of last digits under iterated power maps, and a general bridge principle equating residue-check and inductive proofs via explicit witness polynomials.

\section{Conclusion}

From the observation that $a^5 - a$ is a multiple of $5$ we derived an elementary inductive proof, a factorization, a sharpening to $30$ with matching maximality, a last-digit corollary, and a placement inside Fermat's Little Theorem, revealing the result as one instance of a universal law governed by the primes $p$ with $p-1 \mid n-1$.

\end{document}

