from typing import List

def last_digit(a: int) -> int:
    """Return the last decimal digit of a (nonnegative representative)."""
    return a % 10

def fifth_power_last_digit(a: int) -> int:
    """Last digit of a^5."""
    return (a ** 5) % 10

def iterate_fifth(a: int, k: int) -> int:
    """Last digit after applying x -> x^5 (mod 10) k times, starting from a."""
    x = a % 10
    for _ in range(k):
        x = (x ** 5) % 10
    return x

def digit_fixed_point_table() -> List[int]:
    """For each residue r mod 10, the last digit of r^5 (should equal r)."""
    return [fifth_power_last_digit(r) for r in range(10)]

if __name__ == "__main__":
    print("r         :", list(range(10)))
    print("r^5 mod 10:", digit_fixed_point_table())
    assert digit_fixed_point_table() == list(range(10))
    for r in range(10):
        assert all(iterate_fifth(r, k) == r for k in range(1, 6))
    print("Confirmed: a^5 = a (mod 10), and iterating fifth powers fixes it.")

from typing import List

def is_prime(p: int) -> bool:
    """Primality test by trial division."""
    if p < 2:
        return False
    return all(p % d for d in range(2, int(p ** 0.5) + 1))

def fermat_holds(p: int, lo: int = -10, hi: int = 10) -> bool:
    """Check p | a^p - a for all a in [lo, hi]."""
    return all((a ** p - a) % p == 0 for a in range(lo, hi + 1))

def universal_denominator(n: int, bound: int = 200) -> int:
    """D(n) = product of primes p<=bound with (p-1) | (n-1)."""
    prod = 1
    for p in range(2, bound + 1):
        if is_prime(p) and (n - 1) % (p - 1) == 0:
            prod *= p
    return prod

if __name__ == "__main__":
    for p in [2, 3, 5, 7, 11, 13, 17]:
        assert fermat_holds(p), p
    print("Fermat's Little Theorem verified for primes up to 17.")
    print("D(5) =", universal_denominator(5))   # 30
    print("D(7) =", universal_denominator(7))   # 42
    assert universal_denominator(5) == 30
    assert universal_denominator(7) == 42

